import "fmt"

// safeDiv menggunakan recover untuk mencegah crash
func safeDiv(a, b int) (result int, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("pulih dari panic: %v", r)
		}
	}()
	if b == 0 {
		panic("tidak bisa dibagi dengan nol")
	}
	return a / b, nil
}

func demoDefer() {
	fmt.Println("demoDefer: mulai")
	defer fmt.Println("demoDefer: defer 1")
	defer fmt.Println("demoDefer: defer 2")
	defer fmt.Println("demoDefer: defer 3")
	fmt.Println("demoDefer: selesai")
}

func main() {
	// Demo LIFO defer
	demoDefer()
	fmt.Println()

	// Demo safeDiv
	result, err := safeDiv(10, 3)
	if err != nil {
		fmt.Println("Error:", err)
	} else {
		fmt.Printf("10 / 3 = %d\n", result)
	}

	result, err = safeDiv(10, 0)
	if err != nil {
		fmt.Println("Error:", err)
	} else {
		fmt.Printf("10 / 0 = %d\n", result)
	}
}
